import 'package:analyzer/dart/analysis/utilities.dart';
import 'package:analyzer/dart/ast/ast.dart';
import 'package:analyzer/dart/ast/token.dart';
import 'package:analyzer/dart/ast/visitor.dart';

/// An asset reachable through an accessor of the generated file.
final class GeneratedAsset {
  /// Creates an asset.
  const GeneratedAsset({
    required this.accessor,
    required this.path,
    required this.container,
  });

  /// Name of the getter or field that returns the asset.
  final String accessor;

  /// Path of the asset file, as written in the generated file.
  final String path;

  /// Name the class holding this asset is reached by.
  ///
  /// For the nested style of flutter_gen that is the field of the `Assets`
  /// class — `images` for the assets of `Assets.images` — or the getter of a
  /// subdirectory — `flags` for `Assets.images.flags` — which is what a
  /// `values` iteration reads. Where nothing holds the class, the name of the
  /// class itself.
  final String container;

  @override
  String toString() => '$container.$accessor -> $path';
}

/// Reads the assets out of the source of a file generated by flutter_gen.
///
/// Both shapes are read: a getter returning an `AssetGenImage` and a field
/// holding one. The `values` accessors are left out — they list the assets of
/// their own class and would make every asset look referenced.
///
/// With `package_parameter_enabled`, flutter_gen writes some paths as
/// `packages/<name>/assets/...`, the key another package loads the asset by.
/// The `packages/<packageName>/` prefix is dropped, so [GeneratedAsset.path] is
/// always the path of the file in the project.
List<GeneratedAsset> readGeneratedAssets(String source, {String? packageName}) {
  final unit = parseString(
    content: source,
    throwIfDiagnostics: false,
  ).unit;

  final visitor = _AssetVisitor();
  unit.visitChildren(visitor);

  return visitor.resolved(
    packagePrefix: packageName == null ? null : 'packages/$packageName/',
  );
}

final class _AssetVisitor extends RecursiveAstVisitor<void> {
  final List<_Entry> entries = <_Entry>[];

  /// Class name of a container mapped to the field it is reached by.
  final Map<String, String> containers = <String, String>{};

  /// Assets with their container resolved to the name it is reached by, and
  /// [packagePrefix] dropped from their paths.
  List<GeneratedAsset> resolved({String? packagePrefix}) => <GeneratedAsset>[
    for (final entry in entries)
      GeneratedAsset(
        accessor: entry.accessor,
        path: packagePrefix != null && entry.path.startsWith(packagePrefix)
            ? entry.path.substring(packagePrefix.length)
            : entry.path,
        container: containers[entry.owner] ?? entry.owner,
      ),
  ];

  @override
  void visitMethodDeclaration(MethodDeclaration node) {
    super.visitMethodDeclaration(node);
    if (!node.isGetter) return;

    // `$AssetsImagesFlagsGen get flags => const $AssetsImagesFlagsGen();` — a
    // subdirectory is reached through a getter of its parent, as
    // `Assets.images.flags`.
    final type = node.returnType;
    if (type != null) containers[type.toSource()] = node.name.lexeme;

    _add(
      accessor: node.name.lexeme,
      body: node.body,
      owner: _ownerOf(node),
    );
  }

  @override
  void visitVariableDeclaration(VariableDeclaration node) {
    super.visitVariableDeclaration(node);

    // `static const $AssetsImagesGen images = $AssetsImagesGen();` — the class
    // is reached as `Assets.images`, so the field name is what a
    // `Assets.images.values` reads. Without resolution the initializer of such
    // a field parses as a plain call, so the declared type is the signal.
    final type = _typeOf(node);
    if (type != null) containers[type] = node.name.lexeme;

    final initializer = node.initializer;

    _add(
      accessor: node.name.lexeme,
      body: initializer,
      owner: _ownerOf(node),
    );
  }

  void _add({
    required String accessor,
    required AstNode? body,
    required String owner,
  }) {
    if (body == null || accessor == 'values' || accessor.startsWith('_')) return;

    final path = _firstStringOf(body);
    if (path == null) return;

    entries.add(_Entry(
      accessor: accessor,
      path: path,
      owner: owner,
    ));
  }

  /// Type a variable is declared with, or the class its initializer names.
  static String? _typeOf(VariableDeclaration node) {
    final declaration = node.parent;
    if (declaration is VariableDeclarationList) {
      final type = declaration.type;
      if (type != null) return type.toSource();
    }

    return switch (node.initializer) {
      InstanceCreationExpression(:final constructorName) =>
        constructorName.type.toSource(),
      MethodInvocation(:final methodName) => methodName.name,
      _ => null,
    };
  }

  static String _ownerOf(AstNode node) {
    for (AstNode? parent = node.parent; parent != null; parent = parent.parent) {
      if (parent is ClassDeclaration) return _nameOfClass(parent);
    }

    return '';
  }

  /// Name of [node], read off the token stream.
  ///
  /// The typed accessor for it has been renamed across analyzer versions
  /// (`name` before 14, `namePart` from 14 on), while the tokens have not moved:
  /// the name always follows the `class` keyword. Going through them keeps the
  /// package compiling against the analyzer a host project already pins.
  static String _nameOfClass(ClassDeclaration node) {
    for (Token? token = node.beginToken;
        token != null && token != node.endToken;
        token = token.next) {
      if (token.lexeme == 'class') return token.next?.lexeme ?? '';
    }

    return '';
  }

  static String? _firstStringOf(AstNode node) {
    final visitor = _StringVisitor();
    node.accept(visitor);

    return visitor.value;
  }
}

final class _Entry {
  const _Entry({
    required this.accessor,
    required this.path,
    required this.owner,
  });

  final String accessor;
  final String path;
  final String owner;
}

final class _StringVisitor extends RecursiveAstVisitor<void> {
  String? value;

  @override
  void visitSimpleStringLiteral(SimpleStringLiteral node) {
    value ??= node.value;
  }
}
